begin;

create table public."Dim_Cuenta_Comparativo" (
  "Id_Cuenta_Comparativo" smallint generated by default as identity primary key,
  "Des_Cuenta_Comparativo" varchar not null,
  "Id_Tipo_Cuenta" smallint not null,
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint dim_cta_comp_tipo_cuenta_fkey
    foreign key ("Id_Tipo_Cuenta")
    references public."Dim_TipoCuenta" ("Id_Tipo_Cuenta")
    on update cascade on delete restrict
);

comment on table public."Dim_Cuenta_Comparativo" is 'Catálogo de cuentas vinculadas a los tipos de cuenta para comparativos.';
comment on column public."Dim_Cuenta_Comparativo".estado is 'Estado del registro: 1 activo, 0 inactivo.';
comment on column public."Dim_Cuenta_Comparativo".created_at is 'Fecha y hora de creación del registro.';
comment on column public."Dim_Cuenta_Comparativo".updated_at is 'Fecha y hora de la última actualización del registro.';

alter table public."Dim_Cuenta_Comparativo" enable row level security;
revoke all on table public."Dim_Cuenta_Comparativo" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_Cuenta_Comparativo" to authenticated;

create policy dim_cuenta_comparativo_select_admin on public."Dim_Cuenta_Comparativo"
for select to authenticated using ((select private.is_admin()));
create policy dim_cuenta_comparativo_insert_admin on public."Dim_Cuenta_Comparativo"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_cuenta_comparativo_update_admin on public."Dim_Cuenta_Comparativo"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_cuenta_comparativo_delete_admin on public."Dim_Cuenta_Comparativo"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_cuenta_comparativo_updated_at()
returns trigger language plpgsql set search_path = pg_catalog as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_cuenta_comparativo_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_cuenta_comparativo_updated_at
before update on public."Dim_Cuenta_Comparativo"
for each row execute function private.set_dim_cuenta_comparativo_updated_at();


select setval(
  pg_get_serial_sequence('public."Dim_Cuenta_Comparativo"', 'Id_Cuenta_Comparativo'),
  (select max("Id_Cuenta_Comparativo") from public."Dim_Cuenta_Comparativo"),
  true
);

do $$
declare v_sequence regclass := pg_get_serial_sequence('public."Dim_Cuenta_Comparativo"', 'Id_Cuenta_Comparativo');
begin execute format('grant usage, select on sequence %s to authenticated', v_sequence); end;
$$;

commit;
